-- Onyxia's Lair: the Classic armor, jewelry, cloaks, shields and off-hands that drop there had no item row
-- (the WoW Forever client blanks them), so every one was an invalid loot item and nothing dropped. Rows from the
-- Classic item data: stats as budget shares, armor from the item level formula, Classic sell prices, Classic
-- equip and use spells as item effects, hotfix_data so the client shows them.
DELETE FROM `item_sparse` WHERE `ID` IN (16900,16908,16914,16921,16929,16939,16947,16955,16963,17064,17067,17078,18205,18813);
DELETE FROM `item_effect` WHERE `ID` BETWEEN 9900718 AND 9900737;
DELETE FROM `item_x_item_effect` WHERE `ID` BETWEEN 9900718 AND 9900737;
DELETE FROM `hotfix_data` WHERE `Id` BETWEEN 26113323 AND 26113376;
